import{_ as n,o as r,c as t,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/suchen-gruppenprozesse/gruppenprozesse-zp10-leistungsdaten-holen.png",a="/bilder/suchen-gruppenprozesse/gruppenprozesse-zp10-leistungsdaten-holen-2.png",m=JSON.parse('{"title":"Leistungsdaten für die Zentrale Prüfung übernehmen","description":"","frontmatter":{"title":"Leistungsdaten für die Zentrale Prüfung übernehmen","source_pageid":1146,"source_revision":5918},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/leistungsdaten-holen-gruppenprozesse-zentrale-klausuren.md","filePath":"schild3/suchen-gruppenprozesse/leistungsdaten-holen-gruppenprozesse-zentrale-klausuren.md"}'),l={name:"schild3/suchen-gruppenprozesse/leistungsdaten-holen-gruppenprozesse-zentrale-klausuren.md"};function d(u,e,o,p,h,g){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="leistungsdaten-fur-die-zentrale-prufung-ubernehmen" tabindex="-1">Leistungsdaten für die Zentrale Prüfung übernehmen <a class="header-anchor" href="#leistungsdaten-fur-die-zentrale-prufung-ubernehmen" aria-label="Permalink to &quot;Leistungsdaten für die Zentrale Prüfung übernehmen&quot;">​</a></h1><p>Übernehmen Sie Fächer und gegebenenfalls Noten aus dem aktuellen Lernabschnitt in den Bereich ZP10/ZK. Entscheiden Sie, welche Notenart befüllt und ob vorhandene Daten überschrieben werden sollen.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-zp10-leistungsdaten-holen.png"><img src="'+i+'" alt="Dieser Gruppenprozess holt die konfigurierten Fächer mit ihrer Note aus den Leistungsdaten und trägt beides im Reiter Schüler ➜ ZP 10/ZK ein." loading="lazy"></a></p><p><em>Dieser Gruppenprozess holt die konfigurierten Fächer mit ihrer Note aus den Leistungsdaten und trägt beides im Reiter Schüler ➜ <strong>ZP 10/ZK</strong> ein.</em></p><p>Zu Beginn sind die Leistungsdaten des Reiters <em>Schüler ➜ ZP 10/ZK</em> zu befüllen.</p><p>Zu Beginn der ZP10-Bearbeitung übernimmt der Prozess die Fächer aus den Leistungsdaten des <strong>aktuellen Abschnitts</strong> in <strong>ZP 10/ZK</strong>. Die dort vorhandene Fachnote wird dabei als <strong>Vornote</strong> für die zentrale Prüfung übernommen.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-zp10-leistungsdaten-holen-2.png"><img src="'+a+'" alt="Import der Fächer und der vorhandenen Note in den Reiter ZP 10/ZK." loading="lazy"></a></p><p><em>Import der Fächer und der vorhandenen Note in den Reiter ZP 10/ZK.</em></p><p>Beim Import ist zu entscheiden, als welche Notenart die eingetragenen <em>Note</em> im <em>aktuellen Abschnitt</em> aufzufassen ist.</p><p>In der Regel dürfte aus der im <em>aktuellen Abschnitt</em> aufgrund der erbrachten mündlichen und schriftlichen Leistung schon gegebenen Note die <em>Vornote</em> werden.</p><p>Weiterhin lässt der Haken entscheiden, ob <em>Vorhandene Daten löschen</em> angehakt ist, in diesem Fall werden schon gemachte Eintragungen bei im Reiter <em>Schüler ➜ ZP 10/ZK</em> beim Import überschrieben.</p><p>Wenn Sie <em>Noten ignorieren, nur Fächer holen</em> anwählen, werden nur die Fächerstrukturen bei den Schülern angelegt, ohne auch Noten einzutragen. Diese Schaltfläche kann genutzt werden, um vor dem Holen von Noten sicher zu gehen, dass die Fächer auch alle angelegt sind.</p><p>Wollen Sie die ZP-Teilnoten in den Reiter <em>ZP 10/ZK</em> holen, wird der folgende Gruppenprozess verwendet, wenn diese Noten als Teilleistungen erfasst wurden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Leistungsdaten_holen_(Gruppenprozesse_Zentrale_Klausuren)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5918.</p>',15)])])}const f=n(l,[["render",d]]);export{m as __pageData,f as default};
